  useEffect(() => { void Promise.all([adminApi.listPoints(), adminApi.listVenues(), adminApi.listExhibitions(), adminApi.listExhibitors(), adminApi.listExhibits()]).then(([nextItems, nextVenues, nextExhibitions, nextExhibitors, nextExhibits]) => { setItems(nextItems); setVenues(nextVenues); setExhibitions(nextExhibitions); setExhibitors(nextExhibitors); setExhibits(nextExhibits); }).catch(() => setError("点位数据读取失败。")); }, []);
  const save = async () => { if (!editing?.venueId || !editing.code.trim() || !editing.name.trim()) { setError("请填写所属场地、点位编码和名称。 "); return; } try { const saved = await adminApi.savePoint({ ...editing, code: editing.code.trim(), name: editing.name.trim(), x: Math.min(100, Math.max(0, Number(editing.x) || 0)), y: Math.min(100, Math.max(0, Number(editing.y) || 0)) }); setItems((current) => [saved, ...current.filter((item) => item.id !== saved.id)]); setEditing(null); setError(""); } catch (caught) { setError(caught instanceof Error ? caught.message : "点位保存失败。 "); } };
